  public static class CustomTypeAdapterFactory implements TypeAdapterFactory {
    @SuppressWarnings("unchecked")
    @Override
    public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> type) {
       if (!Audit.class.isAssignableFrom(type.getRawType())) {
         return null; // this class only serializes 'Audit' and its subtypes
       }
       final TypeAdapter<JsonElement> elementAdapter = gson.getAdapter(JsonElement.class);
       final TypeAdapter<Audit> thisAdapter
                        = gson.getDelegateAdapter(this, TypeToken.get(Audit.class));

       return (TypeAdapter<T>) new TypeAdapter<Audit>() {
           @Override
           public void write(JsonWriter out, Audit value) throws IOException {
             JsonObject obj = thisAdapter.toJsonTree(value).getAsJsonObject();
             elementAdapter.write(out, obj);
           }

           @Override
           public Audit read(JsonReader in) throws IOException {
             JsonElement jsonElement = elementAdapter.read(in);
             validateJsonElement(jsonElement);
             return thisAdapter.fromJsonTree(jsonElement);
           }

       }.nullSafe();
    }
  }

  /**
   * Create an instance of Audit given an JSON string
   *
   * @param jsonString JSON string
   * @return An instance of Audit
   * @throws IOException if the JSON string is invalid with respect to Audit
   */
  public static Audit fromJson(String jsonString) throws IOException {
    return JSON.getGson().fromJson(jsonString, Audit.class);
  }

  /**
   * Convert an instance of Audit to an JSON string
   *
   * @return JSON string
   */
  public String toJson() {
    return JSON.getGson().toJson(this);
  }
